 float noise(float2 p) {
  float2 i=floor(p),f=frac(p);f=f*f*(3-2*f);
  return lerp(lerp(hash(i),hash(i+float2(1,0)),f.x),lerp(hash(i+float2(0,1)),hash(i+1),f.x),f.y);
 }
 float fbm(float2 p) { return noise(p)*.57+noise(p*2.03+3.1)*.28+noise(p*4.17-2.4)*.15; }
}; Pattern n;

float2 q=UV*100;float slow=n.fbm(float2(q.x/32,q.y/4));float grain=n.noise(float2(q.x*.075,q.y*4.5+n.noise(q/9)*2));float fine=n.noise(q*8);
float3 color=lerp(float3(.052,.021,.009),float3(.16,.065,.023),slow)*lerp(.85,1.08,grain);
SurfaceNormal=normalize(float3((fine-.5)*.018,(grain-.5)*.028,1));SurfaceRoughness=.38+.17*slow;return color;

